create policy "car images follow car visibility" on public.car_images
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM public.cars c
  WHERE c.id = car_images.car_id AND (c.is_public OR c.owner_id = (( SELECT auth.uid() AS uid))))));
